package entity;
import java.io.Serializable; import java.sql.Date;
public class StudentExperience implements Serializable {private static final long serialVersionUID=1L;private Long experienceId;private String studentId,schoolName,educationLevel,description;private Date startDate,endDate;
 public Long getExperienceId(){return experienceId;}public void setExperienceId(Long v){experienceId=v;}public String getStudentId(){return studentId;}public void setStudentId(String v){studentId=v;}public String getSchoolName(){return schoolName;}public void setSchoolName(String v){schoolName=v;}public String getEducationLevel(){return educationLevel;}public void setEducationLevel(String v){educationLevel=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public Date getStartDate(){return startDate;}public void setStartDate(Date v){startDate=v;}public Date getEndDate(){return endDate;}public void setEndDate(Date v){endDate=v;}}
